function controlSettingsPane(){return `<div class="card"><h2>شروع انبارداری؛ صفر برای اقلام شمارش‌نشده</h2><p class="hint">اقلامی که هرگز در هیچ شمارش کلی نبوده‌اند و اقلام «دقیق» شمارش‌نشده در این مبنا، با مقدار صفر (شمارش‌شده و ناموجود) به مبنای همان تاریخ اضافه می‌شوند. اقلام «سبک» که قبلاً شمارش شده‌اند از شمارش قبلی خودشان ادامه می‌دهند و صفر نمی‌شوند. مقدارهای شمارش‌شده تغییر نمی‌کنند. اگر قلمی در واقع موجود بوده ولی شمارش نشده، صفر گرفتن آن مانده را منفی می‌کند؛ پس فقط برای اقلام واقعاً ناموجود استفاده کنید. اگر در آن تاریخ هیچ مبنای کلی نباشد، یک مبنای کامل با همه اقلام صفر ساخته می‌شود.</p><div class="form-grid"><div class="field"><label>تاریخ شروع انبارداری</label><input id="rayoZeroDate" data-jalali="1" value=""></div><div class="field"><label>زمان مبنا</label><select id="rayoZeroBoundary"><option value="START">ابتدای روز؛ عملیات همان روز محاسبه شود</option><option value="END">پایان روز؛ عملیات از روز بعد محاسبه شود</option></select></div></div><div class="v1012-actions"><button class="btn btn-primary" onclick="RayoInventoryV10.previewZeroFill()">پیش‌نمایش</button><button class="btn" onclick="RayoInventoryV10.previewZeroFillRollback()">پیش‌نمایش بازگردانی آخرین صفرگذاری</button></div><p id="rayoZeroStatus" role="status"></p></div><div class="card"><h2>بازنشانی شمارش‌ها و انبارگردانی‌ها</h2><p class="hint">فقط اسناد شمارش و موجودی اولیه (کل رایو و محلی) باطل می‌شوند؛ انگار هیچ‌کدام ثبت نشده‌اند. ورود خرید، ضایعات/پرتی و سایر حرکت‌های انبار دست‌نخورده می‌مانند — این کار فقط «مبنا»ی محاسبه موجودی را پاک می‌کند، نه تاریخچه واقعی خرید و مصرف را.</p><button type="button" class="btn btn-danger" onclick="RayoInventoryV10.openResetCounts()">بازنشانی همه شمارش‌ها و افتتاحیه‌ها</button></div>`}
