async function ensure(){if(loaded)return true;if(loading){while(loading)await new Promise(r=>setTimeout(r,30));return loaded}loading=true;try{await Promise.all([window.ivEnsureLoaded?.(),window.pcEnsureLoaded?.(),window.supEnsureLoaded?.(),window.crEnsureLoaded?.(true)]);inv=window.getInventoryState?.()||await RAYO_API_GATEWAY.loadOrBootstrap('inventory');pricing=window.getPricingState?.()||await RAYO_API_GATEWAY.loadOrBootstrap('pricing');suppliers=window.getSupplierState?.()||await RAYO_API_GATEWAY.loadOrBootstrap('suppliers').catch(()=>({suppliers:[],items:[],supplierItems:[]}));cash=window.getCashReportState?.()||null;hr=await RAYO_API_GATEWAY.loadOrBootstrap('hr').catch(()=>null);if(!inv||!pricing)throw Error('اطلاعات پایه انبار یا قیمت‌گذاری بارگذاری نشد');if(window.RAYO_API_GATEWAY.getModuleStatus&&['pricing','inventory'].some(k=>window.RAYO_API_GATEWAY.getModuleStatus(k)?.sourceValid!==true))throw Error('Load معتبر انبار و قیمت‌گذاری لازم است');const changed=ensureSchema();/* Data-safety: schema normalization is in-memory only on load; never auto-save. It persists on the next explicit user operation. */await syncLegacyToLedger(false);ui.location=ui.location||inv.settings.mainLocationId;ui.countLocation=ui.countLocation||inv.settings.mainLocationId;loaded=true;return true}catch(e){window.RayoErrorLog?.capture?.(e,{source:'inventory-control-v10-load'});toastX(e.message||'خطا در آماده‌سازی کنترل انبار',true);return false}finally{loading=false}}
