function installDashboardCard(waited=0){if(typeof views==='undefined'||!views.dashboard||views.dashboard.__v10inventory)return;const page=(location.pathname.split('/').pop()||'index.html').toLowerCase();if(page==='index.html'&&!window.__RAYO_DASH_V7__&&waited<60000)return setTimeout(()=>installDashboardCard(waited+200),200);const old=views.dashboard,w=function(){const base=old();if(!loaded){setTimeout(async()=>{await ensure();try{window.refreshDashboardSoon?window.refreshDashboardSoon():renderView()}catch(_){}},0);return base}const t=today(),from=t?`${t.slice(0,8)}01`:'',iv=inventoryValueSummary(t),topVar=topVarianceItems(from,t,5);return base+`<div class="card"><div class="section-head"><div><h2>ارزش ریالی موجودی مواد اولیه</h2><p class="muted">جمع «مقدار موجود × آخرین بهای واحد» برای اقلام دارای موجودی مثبت؛ موجودی منفی یا شمارش‌نشده در جمع نیست.</p></div><a class="btn" href="inventory.html?tab=stock">موجودی اقلام</a></div><div class="grid grid-4"><div class="kpi"><div class="label">ارزش موجودی</div><div class="value">${M(iv.value)}</div><div class="sub">امروز ${E(t)}</div></div><div class="kpi"><div class="label">اقلام دارای موجودی</div><div class="value">${F(iv.inStock,0)}</div><div class="sub">${iv.unpriced?`${F(iv.unpriced,0)} قلم بدون بهای واحد`:'همه دارای بها'}</div></div><div class="kpi"><div class="label">شمارش‌نشده / نامشخص</div><div class="value">${F(iv.unknown,0)}</div><div class="sub">${iv.unknown?'در جمع لحاظ نشده':'همه اقلام مبنا دارند'}</div></div><div class="kpi"><div class="label">موجودی منفی</div><div class="value">${F(iv.negative,0)}</div><div class="sub">${iv.negative?'نیازمند بررسی ثبت‌ها':'ندارد'}</div></div></div></div><div class="card"><div class="section-head"><div><h2>۵ کالای با بیشترین مغایرت این دوره</h2><p class="muted">رتبه‌بندی بر اساس ارزش ریالی مغایرت (مقدار مغایرت × قیمت واحد)، نه فقط مقدار.</p></div><a class="btn btn-sm" href="inventory.html?tab=count">مشاهده کامل</a></div>${topVar.length?`<ol class="v10-top-variance-list">${topVar.map((x,idx)=>`<li><span class="v10-top-variance-rank">${F(idx+1)}</span><b>${E(x.name)}</b><span class="${x.value<0?'danger-text':'positive'}">${x.value<0?'-':'+'}${M(Math.abs(x.value))}</span><small class="muted">${F(x.qty,3)} ${E(x.unit)}</small></li>`).join('')}</ol>`:'<div class="empty">در این دوره شمارش تأییدشده‌ای با مغایرت ریالی معتبر وجود ندارد.</div>'}</div>`};w.__v10inventory=true;views.dashboard=w}
async function install(){if(typeof views==='undefined'||!window.ops||!window.RAYO_API_GATEWAY)return setTimeout(install,80);wrapView();const q=new URLSearchParams(location.search).get('tab');if(TABS.includes(q))window.ops.tab=q;const oldTab=window.opsTab;window.opsTab=function(t){if(TABS.includes(t)){window.ops.tab=t;const u=new URL(location.href);u.searchParams.set('tab',t);history.replaceState({},'',u);renderView();return}return oldTab?.(t)};installPricingVersionTab();wrapRecipeSavers();wrapOpsActions();installDashboardCard();await ensure();patchAnalytics();if(['inventory','reports','dashboard'].includes(currentView))renderView()}
